import type { HTMLAttributes } from 'react'
import { cn } from '@/lib/cn'

// A box that keeps its shape as it grows (CSS aspect-ratio), for a picture or a window that must not reflow: the blog
// card's 5:4 picture, the hero's 2:1 frame. `ratio` is width over height; the content fills it.
export interface AspectRatioProps extends HTMLAttributes<HTMLDivElement> {
  /** Width over height. */
  ratio?: number
}

export function AspectRatio({ ratio = 1, className, style, children, ...rest }: AspectRatioProps) {
  return (
    <div data-ds="aspect-ratio" className={cn('relative w-full overflow-hidden', className)} style={{ ...style, aspectRatio: String(ratio) }} {...rest}>
      {children}
    </div>
  )
}

export default AspectRatio

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
